mapper.select:
SELECT id, inbox_id, experiment_id, visitor_id, group_id, event_kind, event_type, event_name, scene,
       client_event_id,
       idempotency_key, properties_json, status, retry_count, next_retry_at, locked_by, locked_until,
       last_error, event_time, accepted_at, processed_at, created_at, updated_at
FROM pisces_event_inbox
WHERE (
    status IN ('PENDING', 'RETRY')
    AND next_retry_at <= #{now}
)
OR (
    status = 'PROCESSING'
    AND locked_until < #{now}
)
ORDER BY id ASC
LIMIT #{limit}

SELECT id, inbox_id, experiment_id, visitor_id, group_id, event_kind, event_type, event_name, scene,
       client_event_id,
       idempotency_key, properties_json, status, retry_count, next_retry_at, locked_by, locked_until,
       last_error, event_time, accepted_at, processed_at, created_at, updated_at
FROM pisces_event_inbox
WHERE experiment_id = #{experimentId}
  AND (
      (
          status IN ('PENDING', 'RETRY')
          AND next_retry_at <= #{now}
      )
      OR (
          status = 'PROCESSING'
          AND locked_until < #{now}
      )
  )
ORDER BY id ASC
LIMIT #{limit}

