UPDATE pisces_event_inbox
SET status = 'PROCESSING',
    locked_by = #{lockedBy},
    locked_until = #{lockedUntil},
    updated_at = CURRENT_TIMESTAMP
WHERE inbox_id = #{inboxId}
  AND (
      (
          status IN ('PENDING', 'RETRY')
          AND next_retry_at <= #{now}
      )
      OR (
          status = 'PROCESSING'
          AND locked_until < #{now}
      )
  )
